        console.log(Math.min(...common));
        return;
    }

    // No common digit, so we need at least 2 digits
    // Find the smallest digit from a and smallest from b
    const minA = Math.min(...a);
    const minB = Math.min(...b);

    // The smallest pretty integer will be a two-digit number
    // Either minA followed by minB, or minB followed by minA
    const num1 = minA * 10 + minB;
    const num2 = minB * 10 + minA;

    console.log(Math.min(num1, num2));
}
